(()=>{
'use strict';
const statusButton=document.getElementById('offline-status');
let ready=false,busy=false,error='',registration=null;
function setStatus(){if(!statusButton)return;statusButton.className='offline-status '+(ready?'ready':error?'error':'');statusButton.textContent=ready?(navigator.onLine?'✓ Pronto para usar offline':'✓ A funcionar offline'):error?'Offline ainda não preparado':busy?'A guardar para usar offline…':'Preparar uso offline';statusButton.title=ready?'Planos, instruções e sete ilustrações guardados neste dispositivo.':'Abre com internet e aguarda a preparação antes de sair.';if(window.movimentoOfflinePanel)window.movimentoOfflinePanel();}
function workerStatus(worker){return new Promise((resolve,reject)=>{const channel=new MessageChannel(),timeout=setTimeout(()=>reject(Error('Não foi possível confirmar a cópia local.')),15000);channel.port1.onmessage=e=>{clearTimeout(timeout);resolve(e.data);};worker.postMessage({type:'OFFLINE_STATUS'},[channel.port2]);});}
async function check(){const worker=navigator.serviceWorker?.controller||registration?.active;if(!worker)return false;const result=await workerStatus(worker);ready=result.ready===true;if(!ready)error='Alguns ficheiros não foram guardados. Volta a preparar com internet.';else error='';setStatus();return ready;}
async function prepare(){if(busy)return;if(!('serviceWorker'in navigator)||!window.isSecureContext){error='Este navegador não disponibiliza o modo offline. Usa um navegador actualizado num endereço HTTPS.';setStatus();return;}busy=true;error='';setStatus();try{const existing=await navigator.serviceWorker.getRegistration('/');if(existing?.active){registration=existing;await check();if(ready&&!navigator.onLine)return;}registration=await navigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'});await registration.update();if(registration.installing){await new Promise((resolve,reject)=>{const w=registration.installing;w.addEventListener('statechange',()=>{if(w.state==='activated')resolve();if(w.state==='redundant')reject(Error('A preparação falhou. Confirma a ligação e o espaço disponível.'));});if(w.state==='activated')resolve();});}else if(!registration.active){await navigator.serviceWorker.ready;}await check();}catch(e){error=e.message||'Não foi possível preparar a cópia local.';try{await check();}catch{} }finally{busy=false;setStatus();}}
window.movimentoOfflinePanel=()=>{const panel=document.getElementById('offline-panel');if(!panel)return;panel.innerHTML=`<h3>${ready?'Pronto para usar offline':'Prepara o uso sem internet'}</h3><p>${ready?'O aplicativo, os 12 planos semanais, as instruções e as sete ilustrações estão guardados neste dispositivo. As fotos e marcações continuam a ser guardadas localmente.':'Com internet, abre o aplicativo, inicia sessão e espera até aparecer “Pronto para usar offline”. A primeira preparação descarrega as ilustrações e pode demorar, conforme a ligação.'}</p>${error?'<p class="offline-error"></p>':''}<button class="btn" id="offline-check">${busy?'A preparar…':ready?'Verificar cópia offline':'Preparar / tentar novamente'}</button><p class="helper" style="margin-top:12px">Depois, abre pelo histórico do mesmo navegador, pelo endereço guardado ou pelo atalho no ecrã inicial. Não precisas de instalar um APK. Limpar os dados do navegador ou usar navegação privada pode remover a cópia e os registos. Links externos, início de sessão e actualizações precisam de internet.</p>`;if(error)panel.querySelector('.offline-error').textContent=error;panel.querySelector('button').disabled=busy;panel.querySelector('button').onclick=async()=>{if(ready){try{await check();}catch(e){error=e.message;setStatus();}}else await prepare();};};
window.addEventListener('online',setStatus);window.addEventListener('offline',setStatus);if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('controllerchange',()=>check().catch(()=>{}));const app=document.getElementById('app');if(app)new MutationObserver(()=>{if(document.getElementById('offline-panel')&&!document.getElementById('offline-check'))window.movimentoOfflinePanel();}).observe(app,{childList:true});if(statusButton)statusButton.onclick=()=>{if(typeof navigate==='function')navigate('profile');else location.hash='#profile';window.movimentoOfflinePanel();};setStatus();prepare();
})();
